INSERT INTO `software` (`id`, `title`, `softdescription`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, '*Deleting / Removing _Known host_*', '\"@Main server\r\nMain server Login: root\r\nPassword: applied\r\n[root@main-server]# cd .ssh\r\n[root@main-server .ssh]# rm *\r\nremove regular files Known~host? y\r\n[root@main-server .ssh]# exit\r\n\r\n---------------------------------------------------------\r\n\r\n@Backup server\r\nPr\"', '2024-07-24 16:06:51', '2024-07-24 16:06:51', NULL),
(2, 'REPRINTING OF PA SALES REPORT', '\"(Previous Date).\r\n\r\ncd (backup date)\r\ncopy PANAME.dat \\user\\pos\r\n Overwrite \'\\user\\pos\\paname.dat\' (yes/no/all/Quit) ? yes\r\n\"', '2024-07-24 16:07:34', '2024-07-24 16:07:34', NULL),
(3, '\"Monthly Return\" Problem', '\"Backup date \r\n\r\nF:\\backup>cd 061423\r\nF:\\backup\\061423> Copy con redet.dat\r\nPress: F6\r\nPress: Enter\r\nF:\\backup\\061423> Dit redet.dat\"', '2024-07-24 16:08:29', '2024-07-24 16:08:29', NULL),
(4, '\"E.read: client.id   sometimes it will prompts on POS if backup server was activated.\"', '\"Dos prompt:\r\ncd\\pos\r\ndir client*.*\r\n\r\nopen terminal\r\nsu\r\napplied\r\ncd /root/mdc-script/backup/pos\r\nll client*\r\ncp -fp client* /home/manager/backup/pos\r\n\r\n\"', '2024-07-24 16:08:55', '2024-07-24 16:08:55', NULL),
(5, 'TAR PWD FILES', '\"CLICK (OPEN TERMINAL) @ BACKUP SERVER\r\n\r\n[manager@backup-server]$ su\r\nPassword: applied\r\n[root@backup-server]# cd /mnt/ext-hd\r\n[root@backup-server]# ls\r\n\r\nFIND WORKING IORDER:\r\nexample:\r\n[root@backup-server]# tar -xzvf 202212182200iorder\r\n\r\n[root@backup-server]# ls\r\n\r\nFIND IORDER FOLDER:\r\n[root@backup-server]# cd iorder\r\n\r\n[root@backup-server]# rsync -av fwd* 192.168.0.10:/home/manager/main/iorder\r\n\r\nThen Re-index and test.\r\n\r\n\r\nPWD details \r\n\r\ncat pw000123.tmp\"', '2024-07-24 16:09:14', '2024-07-24 16:09:14', NULL),
(6, '*Checking of BACKUP DATE on Managers PC*', '\"At managers PC / Backup server\r\n\r\nOpen *DOSPROMPT* icon\r\n\r\nF:\\BACKUP>cd MMDDYY   <<==== I enter yung date na i che-check\r\nF:\\BACKUP\\MMDDYY> dir\r\n Volume  in drive F is ager/backup\r\n\r\n Directory of F:\\BACKUP\\MMDDYY\r\n*\r\n *FILES*            \r\n\r\n          176 file(s)                 8,896,117 bytes  <<==== Example Only\r\n             0 dir(s)           2,147,450,880 bytes free*\r\n\r\nthen check L \r\n\r\nF:\\BACKUP\\MMDDYY>cd..\r\nF:\\BACKUP>L:\r\nL:\\>cd\\backup\r\nL:\\BACKUP>cd MMDDYY  <<==== I enter yung date na i che-check\r\nL:\\BACKUP\\MMDDYY>dir\r\n   Volume in drive L is anager/main\r\n\r\n   Directory of L:\\BACKUP\\MMDDYY\r\n\r\n**FILES*\r\n\r\n            176 file(s)                 8,896,117 bytes  <<==== Example Only\r\n               0 dir(s)           2,147,450,880 bytes free*\r\n\"', '2024-07-24 16:09:34', '2024-07-24 16:09:34', NULL),
(7, 'All TOS VFD has garbage display. (Sometimes happen after replacing Main Server kit)', '\"Note: Check the VFD unit first, if its new or old VFD model.\r\n> if its NEW model of VFD coordinate to software first.\r\n> if its OLD model of VFD, do the instruction below. \r\n\r\nGo to dos prompt:\r\n\r\nF:\\backup>cd\\iorder\r\nF:\\iorder>dir mod*.*\r\nF:\\iorder>del mod*.*\r\n\r\n>then\r\n>restart/logout all TOS terminal.\"', '2024-07-24 16:09:57', '2024-07-24 16:09:57', NULL),
(8, '\"*DSSR version is not updated. *\"', '\"How to check the version of DSSR? \r\n\r\nGO TO MANAGER\'S PC \r\nOPEN PRINTING OF REPORTS ICON\r\n>ENTER PASSCODE (BRANCH CODE)\r\n>ENTER AUTH. CODE: 2222\r\n>1. POS PRINTED REPORTS\r\n>4. AIMENU 2\r\n>1. DAILY REPORT\r\n>8. DAILY SALES SUMMARY REPORT\r\n>ENTER DATE (MMDDYY)\r\n>VIEW\r\n\r\n\r\n-----------------------------------------------------------------------------------------------------------\r\n-----------------------------------------------------------------------------------------------------------\r\n\r\n                DAILY SALES SUMMARY REPORT *(v1.10)* <<=== *version of DSSR*\r\n\r\nBranch: 9999 - MERCURY DRUG\r\nControl:      70678529642\r\nDate: 10/05/22\r\n-----------------------------------------------------------------------------------------------------------\r\n-----------------------------------------------------------------------------------------------------------\r\n\r\nHow to update DSSR version?\r\n\r\nGo to Main server\r\n\r\nMain server login: root\r\npassword: applied \r\n\r\nNOTE: The password is not visible\r\n\r\n[root@main-server~]# cd /root/mdc-script/main/user/pos\r\n[root@main-server pos]# ll ds*\r\n[root@main-server pos]# rsync ds* /home/manager/main/user/pos\r\n\r\nview DSSR and then check the version if updated\r\nthen check DSSR files if corrected.\"', '2024-07-24 16:10:27', '2024-07-24 16:10:27', NULL),
(9, 'SaleSlip.dat not found', '\"\r\nOPEN \"\"DOS prompt\"\" at BACKUP SERVER\r\nPumunta sa  \"\"backup date\"\"\r\nF:\\backup> cd MMDDYY(e.g 080120)\r\nF:\\backup\\date> dir SaleSlip.dat\r\n\r\nTignan kung mayroong \"\"SaleSlip.dat\"\"\r\nKung walang \"\"SaleSlip.dat\"\" gawin ang sumusunod:\r\n\r\nF:\\backup\\date> copy con SaleSlip.dat - enter\r\n                                                               - press f6 \r\n                                                               - enter\r\nF:\\backup\\date> dir SaleSlip.dat -enter\r\n\r\nCHECK IF 1 FILE(s)\r\n\r\nGENERATE SALESLIP REPORT\"', '2024-07-24 16:10:49', '2024-07-24 16:10:49', NULL),
(10, '\"Unable to print in TOS\"', '\"	Go to TOS station na may error.\r\n\r\n#Solution #1\r\n\r\n>Type \"\"0\"\" sa PA number.\r\n>Choose Exit or Logout\r\n>Press \"\"x\"\" for Linux Utility.\r\n>Press 2 for Printer Utility.\r\n\r\n\"\"Read instruction in the monitor below\"\"\r\n>When to Power Off the printer or Power On the printer.\r\n>Wait to go back to Takeord Window.\r\n>Then try to print.\r\n\r\n===================================================\r\n* If its not working *\r\n\r\n#Solution #2\r\n>Try to fixed cable connection in Printer then repeat solution #1.\r\n\"', '2024-07-24 16:11:09', '2024-07-24 16:11:09', NULL),
(11, '\"Too many active jobs\" prompts on screen in TOS.', '\"Go to TOS station na may error.\r\n\r\n>Type \"\"0\"\" sa PA number.\r\n>Choose Exit or Logout\r\n>Press \"\"x\"\" for Linux Utility.\r\n>Press 2 for Printer Utility.\r\n\r\n\"\"Read instruction in the monitor below\"\"\r\n>When to Power Off the printer or Power On the printer.\r\n>Wait to go back to Takeord Window.\r\n>Then try to print.\r\n\r\n   \"\"FINISH\"\"\r\n\"', '2024-07-24 16:11:31', '2024-07-24 16:11:31', NULL),
(12, 'ICARD FILE', '\"OPEN TOOLBOX \r\n\r\n                  TOOLBOX OPTION\r\n                          ver 3.5\r\n\r\n      [3]    Store Utility\r\n\r\n                  STORE UTILITIES\r\n                          ver 3.5\r\n\r\n      [2]   SUKI ICard File Preparation\r\n\r\n=====================================\r\n                 ICARD FILE\r\nPREPARE                   TO BE TRANSFERRED\r\n=====================================\r\n\r\n     Enter _Date <MmDdYy>:\r\n\r\n\r\nTHEN GET ICARD FILE AT GEN CLERK\'s PC\r\n\"', '2024-07-24 16:11:56', '2024-07-24 16:11:56', NULL),
(13, 'POS FILE', '\"OPEN TOOLBOX \r\n\r\n                  TOOLBOX OPTION\r\n                          ver 3.5\r\n\r\n      [3]    Store Utility\r\n\r\n                 STORE UTILITIES\r\n                         ver 3.5\r\n\r\n      [1]    POS Files Preparation\r\n\r\n=====================================\r\n                  ZP FILE\r\nPREPARE             TO BE TRANSFERRED\r\n=====================================\r\n\r\n     Enter _Date <MmDdYy>:\r\n\r\n\r\nTHEN GET POS FILE AT GEN CLERK\'s PC\r\n\"', '2024-07-24 16:12:20', '2024-07-24 16:12:20', NULL),
(14, '\"SUKI MENU is not Working on TAKEORD ver.2.1a (TOS.EXE)\".', '\"\"\"This procedure is NOT ALLOWED to assist the branch\"\". \"\"TECHNICAL ONLY\"\" but first we NEED to C/O SOFTWARE DEPARTMENT before they do assist to technical. (CLASSIFIED).\r\n\r\nNote: This procedure is to go back old version of TOS MENU which is V20C (TOS.COM).\r\n\r\nSTEP 1. Need to run \"\"*Activ8c.com*\"\" click DOS PROMPT.\r\n     F:\\backup> cd /updates/tos\r\n     F:\\updates\\tos> ls\r\n                              (check if they have V20C)\r\n     F:\\updates\\tos> cd v20c\r\n     F:\\updates\\tos\\v20c> ls \r\n                              (check if they have activ8c.com)\r\n     F:\\updates\\tos\\v20c> *activ8c.com*\r\n                 \"\"You may now Run TOS.COM\"\"\r\n\r\nSTEP 2. Go to takeord where they have a Suki Card Reader.\r\n               ( press Ctrl + alt + F2 ).\r\n     \r\n     localhost login: root\r\n     password: applied\r\n\r\n    [root@localhost ~]# cd /home/manager/.dosemu/drive_c/ (enter)\r\n    [root@localhost drive_c]# ls (enter)\r\n                     (find the \"\"*autoexec.bat*\"\")\r\n    [root@localhost drive_c]# vi *autoexec.bat* (enter)\r\n    \r\nThen find *tos.exe* and change to *tos.com*. How to change??\r\n\r\n     Move the cursor under the *tos.exe*. (Ex._t_os.exe).\r\n  Then double press \"\"*Insert*\"\" (check the lower left if they appear the REPLACE).\r\n\r\nThen type *tos.com* then double press \"\"*Esc*\"\" (check if the Replace on lower left is disappear).\r\n    then Press shift + *:* (check the lower left if they appear the *:* ).\r\nThen type\r\n    *:*wq! (enter)\r\n\r\nCheck if the Suki Menu program is working on Takeord.\r\n\r\nNOTE: PLSS DO NOT SEND THIS PROCEDURE TO TECHNICAL AND WE NEED TO C/O FIRST TO SOFTWARE DEPARTMENT.\"', '2024-07-24 16:12:48', '2024-07-24 16:12:48', NULL),
(15, '\"MecuryDrugBranchReport\" icon unable to proceed.', '\"Open terminal:\r\n\r\n>su\r\n>applied\r\n>cd /home/manager\r\n>ls\r\n\r\n\"\"Check files \"\"MercuryDrugBackend\"\"\r\n======================================\r\n\r\nKung walang Files ng  \"\"MercuryDrugBackend\"\".\r\nOpen terminal:\r\n\r\n>su\r\n>applied\r\n>cd /home/manager\r\n>rsync -av /opt/HomeManager1/MercuryDrugBackend .   <<<\"\" Note may tuldok sa dulo.\"\"\r\n\r\n>chmod -Rf 0777 MercuryDrugBackend\r\n\r\nThen try to open \"\"MercuryDrugBranchReport\"\" icon.\r\n\r\nLogin>Officer1\r\nPassword>Officer1\r\n\r\n\"\"Generate Daily Report.\"\"\r\n\r\n\r\n\r\n\"', '2024-07-24 16:13:11', '2024-07-24 16:13:11', NULL),
(16, 'Rec length cannot proceed in sending\" prompted upon sending of INV.DAT', '\"Possible Reason: Nahaluan ng ibang date or sobra sa files.\r\n\r\nNote: Create ticket then papuntahan sa technician naten, wag sa OIC ipagawa.\r\n\r\nPossible Answer: Go to dos prompt:\r\n\r\nF:\\backup>cd 081522   <<sample date na ayaw masend.\r\nF:\\backup>ED INV.DAT\r\n\r\nNOTE: Always backup INV.DAT first before changing or deleting files some files.\r\n\r\nCheck ung buong laman ng INV.DAT kung may spacing or hindi naka align sa right side.\r\n-delete buong line from right to left lang kung may makita na di naka align.\r\n\r\n\r\n========================================================\r\n\r\n>Go to Toolbox icon\r\n>Store utility\r\n>Press \"\"1\"\" for POS file preperation.\r\n>Enter the date na isesend.\r\n\r\n>Then try to send INV.DAT<\r\n\r\n\r\n\r\n\"', '2024-07-24 16:13:39', '2024-07-24 16:13:39', NULL),
(17, 'To change TOS MENU version. V20C to V21a', '\"POSSIBLE ANSWER:\r\n\r\ngo to dos prompt:\r\n\r\nF:\\backup>cd \\updates\\tos\\\r\nF:\\backup>dir\r\nF:\\backup>cd  V21a\r\nF:\\backup>dir\r\nF:\\backup>activ8c\r\n\r\nthen restart TOS na may suki and test.\"', '2024-07-24 16:14:02', '2024-07-24 16:14:02', NULL),
(18, 'REINDEX FILES', '\"BACKUP SERVER\r\n\r\nNOTE: SHUTDOWN all TOS Terminals and Rx Terminal.\r\n\r\n(CLICK DOS PROMPT)\r\n\r\nSTEP1:\r\nF:\\backup>cd\\iorder\r\nF:\\iorder>utility\r\n\r\nPassword pls. - tqbfjotld\r\n\r\nPassword:tqbfjotld (The quick brown fox jumps over the lazy dog)\r\n\r\n\r\n> 1. Reindex Files\r\n> 2. Create/Update TOSPRO FILE\r\n> 3. Create/Update Rx FILE\r\n> 4. Enter/Update Item Location\r\n> 5. Update PAMASTER.DBF         \r\n> 6. Quit\r\n\r\nPRESS: 1 \r\n\r\n	Reindex all takeord Files\r\n\r\n		TO Reindex : (Note Order station)\r\n		 Itemaster file\r\n		 Price file\r\n		 Pamaster file\r\n		 Paorder file\r\n		 PA\'s Order file\r\n		 Promo file\r\n		 Equivalent file\r\n		 Tospro file\r\n		 Rx file\r\n		 OSCA / PWD files\r\n		 Non-Therapeautic file\r\n		 Generic List in Takeord\r\n		 Deleted List in Takeord\r\n		 Account\'s File\r\n		 Quit\r\n\r\nPRESS: 4 \r\n> 4. Enter/Update Item Location\r\n	ENTRY/UPDATE OF ITEM LOCATION\r\n	\r\n	....this procedure needs a password\r\n	Enter password - PASSWORD\r\n\r\n(ALL CAPS PASSWORD)\r\n\r\n	Proceed? (Y/N) - y\r\n		>Reindex Location File\r\n	Proceed? (Y/N) - y\r\n		-enter\r\nQUIT\r\nF:\\iorder>exitemu\"', '2024-07-24 16:14:21', '2024-07-24 16:14:21', NULL),
(19, 'All TOS terminals \"Printer not ready\" prompts on screen after Enter \"confirm\" transaction', '\"POSSIBLE REASON:\r\n\r\nNag update ang branch sa item location. then na lagyan ng * ang rightside column.\r\n\r\nto check item location, \r\n\r\ngo to dos prompt:\r\n\r\ncd\\iorder\r\nutility\r\ntqbfjotld  <=== type password\r\n\r\n4.Entry/Update item location.\r\n\r\nEnter item location.\r\n==============================================\r\n\r\nPOSSIBLE ANSWER:\r\n\r\n1.Ask the branch kung meron nag update ng item location.\r\n \r\n2.Advice the branch to check item location. then kunin sa branch officer kung anung item number ung nag priprinter not ready after maconfirm ang transaction.\r\n \r\n3.go to dos prompt:\r\n\r\ncd\\iorder\r\nutility\r\ntqbfjotld  <=== type password\r\n\r\n4.Entry/Update item location.\r\n\r\nEnter item location.\r\n\r\nInput ung exact item number then check ko may * sa right column at burahin.\r\n\r\nAfter mabura. \r\n\r\nReindex item location. \r\n\r\nTesting the item in takeord station.\r\n\r\nPag naghang mga takeord ipareindex lang. Normal reindex only for takeord.\r\n\r\nPS.> Ang branch officer lang ang pwede magbura sa item location. Or advice to call IT for further assistance.\r\n\r\n\"', '2024-07-24 16:14:40', '2024-07-24 16:14:40', NULL),
(20, 'GTZ REPORT or DSSR REPORT PROBLEM #1', '\"NOTE: CASE TO CASE problem po ito. Mas mabuti na humingi pa din ng advice sa mas nakakaalam..\r\n\r\n\r\nMeron GTZ reading ang branch, pero wala sa DSSR and hindi din nag accumulate.\r\n\r\n\r\nPOSSIBLE REASON:\r\nNagkaroon ng Special character nahumalo sa EJ files.\r\n\r\nPOSSIBLE ANSWER:\r\nGawan ng report muna.\r\nPapuntahan sa technician. \r\nThen papacheck ang EJ files para burahin ang Special character sa header.\r\n\r\nNote: Before ipagalaw ang EJ files endorse first to sir Nes or sir Jonie.\r\n\"', '2024-07-24 16:15:04', '2024-07-24 16:15:04', NULL),
(21, 'GTZ REPORT or DSSR REPORT PROBLEM #2', '\"NOTE: CASE TO CASE problem po ito. Mas mabuti na humingi pa din ng advice sa mas nakakaalam..\r\n\r\nAccumulated sales in POS #4 dated  072422 and 072522 <== sample ng date na may problem.\r\n\r\nSa DSSR ng 072422 meron laman pero accumulate pa din siya sa DSSR ng 072522.\r\nParehas may GTZ reading reciept.\r\n\r\nPOSSIBLE REASON:\r\nNag hang ang POS pero may printout pa din ng GTZ so possible pumasok pa din siya sa backup server, pero naiwan ung sales sa kaha.\r\n\r\nPOSSIBLE ANSWER: \r\n\r\nAdvice the branch to actual the sales then patawagin ang branch officer ng end of the month for MSSR report. \r\n\r\nPossible hindi magtally ang DSSR and MSSR kapag nag generate ng MSSR. kaya dapat patawagin ang branch para ma edit pansamantala ang EJ na may problema.\r\n\r\n\r\nPara ma edit ang EJ.00# na may problema at maitama ang MSSR.\r\n\r\nGo to dos prompt :\r\n\r\ncd 072422 <== date na nag cause ng paghalo\r\nren EJ.004 ralph <== ikaw na bahala kung anu rename gusto mo.\r\n\r\nthen pa generate mo na si branch ng MSSR nila para magtally sila sa DSSR. After nila mag generate ibalik ang tamang EJ.\r\n\r\nGo to dos prompt :\r\n\r\ncd 072422\r\nren ralph EJ.004\r\n\r\n\r\nJOBS DONE.!!!\r\n\r\n\r\nNOTE AGAIN::\r\n\r\nKung makulit pa din ang branch at hindi madala sa verbal explanation. GAwan ng report or ticket and endorse to sir Jonie and get an advise.\r\n\r\n\r\n\"', '2024-07-24 16:15:26', '2024-07-24 16:15:26', NULL),
(22, 'GTZ REPORT or DSSR REPORT PROBLEM #3', '\"NOTE: CASE TO CASE problem po ito. Mas mabuti na humingi pa din ng advice sa mas nakakaalam.\r\n\r\nNag 0 yung POS # 4 sa DSSR pero may laman yung GTZ nila sa POS #4 \r\n\r\nPOSSIBLE REASON:\r\n>LATE na nag GTZ yung POS #4\r\n>Nag GTZ sila ng POS #4 pag katapos mag closing procedure sa backup server\r\n\r\nPOSSIBLE ANSWER:\r\nAdvice the branch to write an explanation letter for why it is late perform GTZ reading.\r\nThen advice the branch to attach GTZ reading reciept to yesterday date\r\n\r\nALTERNATIVE SOLUTION:\r\nKung ang branch OFFICER ayaw gumawa ng explanation letter at mapilit kung paano masolution ang problema nila. gawina ang mga nasa ibaba.\r\n\r\nNOTE: kung may transaction na wag na i pa delete yung ej_r.004 sa F:\\POS> kung sumama na.\r\n\r\nNOTE: Make sure wala pang transaction yung POS #4\r\n\r\nopen dosprompt @managers pc / back up server.\r\n\r\nF:\\Backup>cd 071822\r\n\r\nF:\\backup\\071822>copy \\pos\\ej_r.004\r\n\r\nF:\\backup\\071822>ren ej.004 004\r\n\r\nF:\\backup\\071822>copy ej_r.004+004=EJ.004\r\n\r\nIview yung Dssr check kung sumama na.\r\n\r\nIrename yung ej_r.004 kung wala pang transaction yung pos 4\r\n\r\npunta ng F:\\POS>\r\n\r\nF:\\BACKUP>cd\\pos\r\n\r\nF:\\POS>ren ej_r.004 (folder)\"', '2024-07-24 16:16:03', '2024-07-24 16:16:03', NULL),
(23, '\"Unable to get sukifile. Error f:\\lsuki\\attach directory mostly in new branches. \"', '\"Dos prompt\r\n\r\ncd\\lsuki\r\ned lsuki.ini\r\n\r\nedit code 000 to branch code of branch. 1000-1099 = A00\r\n                                                                1100-1199 =B00\r\n\r\nfile\r\nsave.\r\n\r\ngo to lsuki menu icon. \r\n\r\nreindex\r\nprepared.\r\n\r\nthe get suki file.\"', '2024-07-24 16:16:22', '2024-07-24 16:16:22', NULL),
(24, 'RX TERMINAL HAS ALWAYS INCORRECT TIME AND DATE', '\"RX terminal\r\nOpen GNOME terminal\r\n[manager @rx-terminal ~]$ su\r\npassword: applied\r\n\r\n[root@rx-terminal ~]$ timedatectl set-time HH:MM:SS\r\n\r\nsample:\r\n[root@rx-terminal ~]$ *timedatectl set-time 10:23:00*\r\n\r\nthen restart RX terminal.\r\n\r\n_*NOTE: FOR NEW RX TERMINALS ONLY!!!!!!*_\r\n\"', '2024-07-24 16:16:44', '2024-07-24 16:16:44', NULL),
(25, 'Configured IP Address of the NEW RX TERMINAL.(CENTS).', '\"INSTRUCTION:\r\nClick the GNOME TERMINAL beside the START MENU\r\nat Lower left of the monitor.\r\n\r\n===================\r\nLogin: su\r\nPassword: applied\r\n===================\r\n\r\nUse Up Arrow key and find \"\"nmtui\"\".\r\n\r\nroot@rx - terminal manager ]# nmtui\r\n\r\n                            NetworkManager TUI\r\n\r\n             Please select an option\r\n                           Edit a Connection\r\n                        Activate a Connection\r\n                       Set system hostname\r\n\r\nSelect \"\"Edit a Connection\"\".\r\n                     Then find \"\"enp2s0\"\".\r\n\r\nSelect \"\"enp2s0\"\" then click <Edit....> \r\n\r\nFind IPv4 CONFIGURATION\r\n                             Addresses: 192.168.0.30/24\r\n                                                <Add.....>\r\n                             Gateway   : 192.168.0.254\r\n                      DNS Servers   : 172.20.0.1\r\n                                                 8.8.8.8\r\n                                                 0.0.0.0\r\n                                                 <Add.....>\r\n\r\nThen scroll down then click <OK>\r\n\r\nthen check if they have a Enthranet or check www1.chainstore.net\r\n\"', '2024-07-24 16:17:03', '2024-07-24 16:17:03', NULL),
(26, 'FILES TO SEGREGATE', '\"BARCTRAN.DAT\r\nCLERCK.DAT\r\nGIFTTRAN.DAT\r\nGPAY.DAT\r\nHOUSECHG.DAT\r\nICARD.DAT\r\nICOMPLY.DAT\r\nINV.DAT\r\nORDER.DAT\r\nOSCA.DAT\r\nPAREC.DAT\r\nPROD.DAT\r\nPWD16.DAT\r\nREDEEM.DAT\r\nSUKI.DAT\r\nSUPCOUP.DAT\r\n\r\nCREDINFO.LOG\r\nDEBIT.LOG\r\nSUSPEND.LOG\r\n\r\nEJ.001\r\nEJ.002\r\nEJ.003\r\nEJ.004\r\n\r\n\"', '2024-07-24 16:17:43', '2024-07-24 16:17:43', NULL),
(27, 'REPRINTING OF PHARMA STATISTIC REPORT', '\"Reprinting Pharma Asst Report.(Previous Date)\r\n\r\ncd (backup date)\r\ncopy clerk.dat \\user\\pos\r\n Overwrite \'\\user\\pos\\clerk.dat\' (yes/no/all/Quit) ? yes\r\n\r\nThen try print .......\"', '2024-07-24 16:17:59', '2024-07-24 16:17:59', NULL),
(28, 'How to mount USB on Main and Backup Server.', '\"Step 1: Ctrl alt F2.\r\n\r\nlogin : root\r\npass : applied\r\n\r\nStep 2: Insert Flash Drive (check what sd on Assuming drive cache).\r\n                                            (for example: sdb : Assuming drive cache.)\r\n\r\nroot@main-server # ls -l /dev/sd*\r\n\r\nStep 3:\r\nroot@main-server# mount /dev/sdb1 /media/usb\r\n\r\nhow to umount USB ?\r\nroot@main-server# umount /media/usb\r\n\r\n(remove flash drive)\r\n\r\n************************************************************\r\nMounting flashdrive in main server to copy back up date\r\n\r\nLog in main server root applied\r\nType fdisk -l\r\nType mount /dev/sdb1 /media\r\nType cd /media\r\nType mkdir \"\"name of folder\"\"\r\nType cd /\"\"name of folder\"\"\r\nType rsync -av /home/manager/main/backup/\"\"date of file then space period.\"', '2024-07-24 16:18:21', '2024-07-24 16:18:21', NULL),
(29, 'Alternative way to Shut down Main server', '\"main-server login: root\r\nPassword:\r\n\r\nroot@main-server ~]# cd /home/poweroff/\r\nroot@main-server ~]# ll\r\nroot@main-server ~]# ./powerDown10.sh\"', '2024-07-24 16:18:49', '2024-07-24 16:18:49', NULL),
(30, 'Unable to transact Gift cert on POS (ACTIVATED BACKUP SERVER)', '\"open terminal\r\nsu\r\napplied\r\ncd/ root/mdc-script/main/pos\r\ncp gift*.dat /home/manager/main/pos\r\novewrite? Y\"', '2024-07-24 16:19:30', '2024-07-24 16:19:30', NULL),
(31, 'FINAL UPDATE AT TOOLBOX', '\"OPEN TERMINAL\r\n\r\nTYPE:\r\nsudo backup/pos/update.sh\"', '2024-07-24 16:19:50', '2024-07-24 16:19:50', NULL),
(32, 'Changing MAC address of POS & TOS', '\"Main server\r\n\r\nLogin:root\r\nPassword:applied\r\n\r\n[root@main-server ~]# cd /etc/\r\n[root@main-server etc]# vi dhcpd.conf\r\n\r\nPRESS INSERT TWICE\r\n\r\nREPLACE Prompt on lower left part\r\n\r\nReplace (MAC ADDRESS)\r\n\r\nPRESS ESC TWICE\r\n\r\nTYPE \r\n\r\n:wq! (to save and quit)\r\n:q!  (to quit only)\r\n\r\n[root@main-server etc]# service dcphd restart\r\n\"', '2024-07-24 16:20:09', '2024-07-24 16:20:09', NULL),
(33, 'No \"mercuryMenu.sh\" at Main server.', '\"Main Server Login: root\r\nPassword: applied\r\n[root@main-server~]# cd /opt/Script/\r\ncheck (mercuryMenu.sh) File\r\n[root@main-server~ Script]# ll mer*\r\n[root@main-server~ Script]# cp -fp mercuryMenu.sh /home/manager\r\n\r\nBack to [root@main-server~]# then proceed.\r\n\r\n[root@main-server~]#./byPassManPC.sh\r\n\r\n        Manager\'s PC Not Detected!!!\r\n        By Pass Manager\'s PC Permitted...\r\n\r\n[manager@main-server~]#./mercuryMenu.sh\"', '2024-07-24 16:20:38', '2024-07-24 16:20:38', NULL),
(34, '\"Not a database file\" prompted upon re-indexing onhand file.', '\"Deleted drinv.dbf and drinv1.idx at F:\\IORDER.\r\n\r\nGo to dos prompt.\r\n\r\ntype\r\n\r\nF:\\backup> cd\\iorder\r\nF:\\iorder>del drinv.dbf\r\nF:\\iorder >del drinv1.idx\r\n\r\n\"', '2024-07-24 16:20:57', '2024-07-24 16:20:57', NULL),
(35, '\"Number already used\" Prompted upon inserting of Return Reference number on POS', '\"on DOS prompt\r\nF:\\Backup> cd\\pos\r\nF:\\POS> del rrt*.tmp\r\nF:\\POS> del rrd*.tmp\"', '2024-07-24 16:21:14', '2024-07-24 16:21:14', NULL),
(36, 'Documents has no pages', '\"@MAIN SERVER\r\nMain Server Login: root\r\nMain Server Pass:  applied\r\n===============================================\r\nroot@ Main Server]# cd /Files\r\nroot@ Main Server]# vi joMysqlReportDefault.sh\r\n\r\nFIND: fourdigit = \"\"1132\"\" [DEFAULT]\r\npress insert twice:\r\nREPLACE Th\"', '2024-07-24 16:21:31', '2024-10-11 18:49:55', NULL),
(37, 'COPY Icon Mercury Drug Branch Reports on Backup Server.', '\">Right click on Screen then click Open Terminal.\r\n\r\n[manager@backup-server]# su\r\nPassword: applied\r\n\r\n[root@backup-server manager]# cd /opt/HomeManager1/\r\n[root@backup-server HomeManager1]# ls\r\n      >then check if they are \"\"Mercury Drug Branch Reports.desktop\"\"\r\n\r\n[root@backup-server HomeManager1]# cp -fp MercuryDrugBranchReports.desktop /home/manager/Desktop/\r\n[root@backup-server HomeManager1]# exit\r\n\r\n\r\nThen Check the icon on Desktop.\"', '2024-07-24 16:21:50', '2024-07-24 16:21:50', NULL),
(38, '\"Price Verifier stucked in SFTP upon booting\"', '\">Do not turn off the Price Verifier CPU and go to the \r\n                                                    Backup Server then Open Terminal.\r\n\r\nLogin: su\r\nPassword: applied\r\n\r\nRemote the Price Verifier CPU IP Address\r\nPriceVerifier 1 = 192.168.0.51\r\nPriceVerifier 2 = 192.168.0.52\r\nPriceVerifier 3 = 192.168.0.53\r\nPriceVerifier 4 = 192.168.0.54\r\n\r\nExample for Price Verifier 1:\r\n\r\nroot@BackupServer manager]# ssh 192.168.0.51\r\nAre you sure you want to continue connecting (yes/no) ? yes\r\nroot@192.168.0.51\'s password: applied\r\n\r\n[root@localhost ~]# cd /root/.ssh\r\n[root@localhost .ssh]# rm *\r\n[root@localhost .ssh]# exit\r\n\r\nRestart the Price Verifier.\"', '2024-07-24 16:22:16', '2024-07-24 16:22:16', NULL),
(39, 'HOUSE CHARGE (RETAIL RETURN)', '\"TOS\r\n\r\nTOS MENU\r\nF12\r\nREGULAR RETURN\r\n	INPUT TOS ITEM THEN CONFIRM\r\nGET (ORDER #)\r\n\r\nGOTO\r\nPAYMENT TERMINAL\r\n	NEW HOUSE CHARGE\r\n		INPUT INFORMATION\r\n		POS TYPE : RETAIL 		ORDER No: (FROM TOS REGULAR RETURN)\r\n\r\nCREATE HOUSE CHARGE TRANSACTION DATA (Y/N) ? Y\r\n\r\nESC\r\n\r\nGOTO\r\nRETURN TRANSACTION\r\n	INFORMATION ENTRY 	   (from Original Reciept)\r\n	               DATE OF PURCHASED:\r\n		  ORIGINATING STORE:\r\n		 DOCUMENT NUMBER: (INVOICE # )\r\n	    TOTAL AMOUNT PURCHASED:\r\n  	               REASON FOR RETURN:\r\n			   POS TYPE: RETAIL\r\n		      RETURN NUMBER: (FROM TOS REGULAR RETURN)\r\n\r\nCREATE RETURN TRANSACTION  DATA (Y/N) ? Y\r\n	(PRINTED PINK COPY) \r\n\r\nPOS\r\n\r\nPRESS\r\nRETURN KEY\r\n	RETURN # (PRINTED PINK COPY)\r\n		        RETURN TRANSACTION\r\n		1. RETURN FOR ITEMS PURCHASED\r\n		2. RETURN OF GIFT CERTIFICATE\r\n		3. RETURN OF STORE CREDIT\r\n\r\n			SELECT OPTION 1\r\n			\r\n			ORIGINAL TRANS # (TXN# from original receipt)		\r\n\r\nCHARGE INVOICE KEY\r\n	01 ORDER RECALL\r\n	02 SELF-SERVICE\r\n		ENTER HOUSE CHARGE TYPE 1\r\n\r\n			PRESS ORDER RECALL KEY\r\n				ORDER NO. (FROM TOS REGULAR RETURN)\r\nTOTAL\r\nENTER\"', '2024-07-24 16:22:34', '2024-07-24 16:22:34', NULL),
(40, '\"SUSPEND.LOG NOT FOUND\" prompted on screen upon printing of Suspended report.', '\"Create SUSPEND.LOG at F:\\BACKUP\\DATE on the Backup Server.\r\n\r\nOPEN \"\"DOS prompt\"\" at BACKUP SERVER\r\n\r\nF:\\backup> cd MMDDYY(e.g 080120)\r\nF:\\backup\\date> dir suspend.log\r\n\r\nKung walang \"\"suspend.log\"\" gawin ang sumusunod:\r\nF:\\backup\\date> copy con suspend.log - enter\r\npress f6 then enter\r\n\r\nThen print..\"', '2024-07-24 16:22:53', '2024-07-24 16:22:53', NULL),
(41, 'PNSTM report', '\"OPEN \"\"DOS prompt\"\" at BACKUP SERVER\r\n\r\nF:\\backup> cd MMDDYY(e.g 080120)\r\nF:\\backup\\date> dir pnstm.dat\r\nTignan kung mayroong \"\"pnstm.dat\"\"\r\n\r\nKung walang \"\"pnstm.dat\"\" gawin ang sumusunod:\r\nF:\\backup\\date> copy con pnstm.dat - enter\r\npress f6 then enter\r\nF:\\backup\\date> dir pnstm.dat\r\n\r\nThen try to ge at Gen clerk PC.\"', '2024-07-24 16:23:14', '2024-07-24 16:23:14', NULL),
(42, 'SUKI ICARD TRANSACTION hanged in POS.', '\"o======================================o\r\n	               TOOLBOX OPTION\r\n	                         ver 2.9\r\no======================================o\r\n\r\n     [1] Price Verifier Option\r\n     [2] Server/Manager\'s PC Option\r\n     [3] Store Utility\r\n     [4] Store Personalization\r\n     [5] Queing System Option\r\n\r\n     [8] Final Update\r\n     [0] Exit/Stop\r\n\r\no======================================o\r\n  Enter your option [1,2,3,4,0] --> 3\r\n\r\n***********************************************************.\r\n\r\no======================================o\r\n	               STORE UTILITIES\r\n	                         ver 2.9\r\no======================================o\r\n\r\n     [1] POS File Preparation\r\n     [2] SUKI ICard File Preparation\r\n     [3] SUKI ICard Detail File Preparation\r\n     [4] Online Discount File Checking\r\n     [7] Update SS-Icard Reference File\r\n     [8] Check Server File Properties (chmod)\r\n\r\no======================================o\r\n               --(TRANSACTION OPTIONS)--\r\n\r\n     [A] eM-PAY\r\n     [B] Cancelled\r\n     [C] Returned\r\n     [D] Suspended\r\n     [E] EWT\r\n     [F] ON-LINE\r\n     [G] OCNR\r\n     [H] Barcoded Coupon\r\n     [I] Sales Classification\r\n     [X] IMPROPER USER LOGOUT\r\n     [9] Return to Main Option \r\n\r\no======================================o\r\n\r\n  Enter your option [1,2,3,4,5,9]: --> 7\"', '2024-07-24 16:23:42', '2024-07-24 16:23:42', NULL),
(43, '\"Company does not exist\" or \"Subsidiary does not exist\" Prompted on Takeord Terminals.', '\"\"\"Company does not exist\"\" Prompted on Takeord Terminals. suki icard transactions.\r\n\r\n(ASK THE COMPANY OF ICARD)\r\n\r\no======================================o\r\n                    TOOLBOX OPTION\r\n                             ver 2.9\r\no======================================o\r\n\r\n      [1] Price Verifier Option\r\n      [2] Server/Manager\'s PC Option\r\n      [3] Store Utility\r\n      [4] Store Personalization\r\n      [5] Queuing System Option\r\n\r\n      [8] Final Update\r\n      [0] Exit/Stop\r\n\r\no======================================o\r\n  Enter your option [1,2,3,4,0] --> 2 (ENTER)\r\n\r\n***********************************************************\r\n\r\no======================================o\r\n           SERVER/MANAGER\'S PC OPTION\r\n                               ver 2.9\r\no======================================o\r\n\r\n      [1] SUKI Icard Option\r\n      [2] Manager\'s         PC Check Config\r\n      [3] Server\'s         PC Check Config\r\n      [4] RX\'s         PC Check Config\r\n\r\n      [8] SERVER\'s DATE and TIME Adjusment\r\n      [9] Return to Main server Option\r\n\r\no=======================================o\r\n  Enter your option [1,8,9] --> 1 (ENTER)\r\n\r\n*************************************************************\r\n\r\no=======================================o\r\n                       SUKI ICARD OPTION\r\n                                 ver 2.9\r\no=======================================o\r\n\r\n      [1] Offline Record UPDATE\r\n      [2] Online Record UPDATE\r\n      [3] Branch Record Inquiry\r\n\r\n      [8] DELETE RECORD OPTION\r\n      [9] Return to Server/Manager\'s PC Option\r\n\r\no=======================================o\r\n  Enter your option [1,2,3,8,9] --> 1 (ENTER)\r\n\r\nListed Accounts can be added/records can be updated, these can also be\r\ndeleted using option#8 at SUKI ICARD OPTION - DELETED RECORD OPTION\r\n\r\n--------------------------------------------------------------------------------------------------------------\r\n\r\n        1)  MERCURY DRUG CORPORATION\r\n        2)  MAXICARE HEALTHCARE CORP\r\n        3)  MERCK SHARP & DOHME (LLC)\r\n        4)  MERCURY GROUP OF COMPANIES INC\r\n        5)  MILESTONE DEVELOPMENT CORP.\r\n        6)  TELSTAR MANUFACTURING CORP.\r\n        7)  MEDICAL CENTER TRADING CORP.\r\n        8)  MSD ANIMAL HEALTH (PHILS.), INC\r\n        9)  INFOWORX, INC.\r\n        10) MEDICARD PHILIPPINES, INC.\r\n        11) PHILUSA CORPORATION\r\n        12) LCC HEALTH CARE CONSULTANCY\r\n        13) AGB NIELSEN MEDIA RESEARCH\r\n        14) TRINITY FRANCHISING & MGT\r\n        15) PHILIPPINE VENDING CORPORATION\r\n        16) PHILIPPINE FOOD SERVICE GROUP\r\n        17) INNOVENDCORPORATION\r\n        \r\n        X) GO BACK TO SUKI ICARD OPTION\r\n--------------------------------------------------------------------------------------------------------------\r\nEnter your option TO BE INCLUDED [1,2]...X]: -->  (ENTER COMPANY OF ICARD)\r\n\r\n***********************************************************************\r\nSTEP #2\r\n(CLOSE TOOLBOX THEN OPEN NEW)\r\n\r\n\r\n      [1] Price Verifier Option\r\n      [2] Server/Manager\'s PC Option\r\n      [3] Store Utility\r\n      [4] Store Personalization\r\n      [5] Queuing System Option\r\n\r\n      [8] Final Update\r\n      [0] Exit/Stop\r\n\r\no======================================o\r\n  Enter your option [1,2,3,4,0] --> 3 (ENTER)\r\n\r\n     [1] POS File Preparation\r\n     [2] SUKI ICard File Preparation\r\n     [3] SUKI ICard Detail File Preparation\r\n     [4] Online Discount File Checking\r\n     [7] Update SS-Icard Reference File\r\n     [8] Check Server File Properties (chmod)\r\n\r\n  Enter your option [1,2,3,4,0] --> 7 (ENTER)\r\n\r\no======================================o\r\n__________________________________________________________________\"', '2024-07-24 16:24:01', '2024-07-24 16:24:01', NULL),
(44, 'NFS, DHCPD, XINETD', '\"At Main server \r\n\r\nservice dhcpd restart\r\n\r\nservice nfs restart\r\n\r\nservice xinetd restart\"', '2024-07-24 16:24:24', '2024-07-24 16:24:24', NULL),
(45, 'Rx Terminal set up configuration', '\"OPEN TERMINAL\r\n\r\nsetup\r\n\r\nIP address:                 192.168.0.30\r\nTAB\r\nNetmask:                    255.255.255.0\r\nTAB\r\nDefault gateway (IP): 255.255.255.0\r\n\r\nPrimary nameserver: 172.20.0.1\r\n\r\nwww1.chainstore.net \"', '2024-07-24 16:25:03', '2024-07-24 16:25:03', NULL),
(46, 'PRINTER CONVERSION NEEDED FILES', '\"POS #\r\n\r\nEPSON H6000\r\nEPSON.001\r\nEPSONTH.001\r\nTHERMAL.001\r\n\r\nDOT MATRIX\r\nEPSON.001\r\n\r\n2NR PRINTER\r\n2NR.001\r\n\r\nIMAGE\r\nEPSON DOT MATRIX & H6000\r\nMA\r\nT\r\nE\r\n\r\n2NR\r\nL\r\n\"', '2024-07-24 16:25:24', '2024-07-24 16:25:24', NULL),
(47, '\"error\" prompted on suki icard on TOS terminal.', '\"Check at Backup server branch.dat if my spacing.\r\n\r\nF:\\backup>cd\\pos\r\nF:\\pos>type branch.dat\r\nExample:\r\nIncorrect\r\n1000 - MDC 100\r\n\r\nF:\\pos>ed branch.dat\r\nCorrect\r\n1000-MDC 100\r\n\r\nsave and exit.\r\n\r\n\"\"Error\"\" upon insert ng Icard\r\nAt Main server branch.dat if my spacing sa baba.\r\n\r\ncd /home/manager/main/pos\r\nvi branch.dat\r\n\r\n\"', '2024-07-24 16:25:43', '2024-07-24 16:25:43', NULL),
(48, '\"Out of range\" Price verifier', '\"At PRICE VERIFIER put a Keyboard\r\nCrtl + alt + F2\r\n\r\nLogin:root\r\nPassword:applied\r\n\r\n[root@main-server ~]# cd /root/etc/X11/\r\n[root@main-server ~]# vi xorg.conf\r\n\r\nPAGE DOWN\r\nGo to section \"\"Monitor\"\"\r\n\r\n	HorizSync	30 - 60\r\n	VertRefresh 	60 65\r\n\r\nPress 2 INSERT to replaced\r\n\r\n	HorizSync	30 - 82\r\n	VertRefresh 	50 - 70\r\n\r\nPress 2 times ESC\r\nthen to save :wq!\r\n\r\n[root@main-server ~]#exit\r\nRESTART\r\n\r\nLogin:poweroff\r\nPassword:poweroff\r\n\"', '2024-07-24 16:26:05', '2024-07-24 16:26:05', NULL),
(49, 'ICOMPLY FILE', '\"OPEN TOOLBOX \r\n\r\n         TOOLBOX OPTION\r\n                   ver 3.5\r\n\r\n      [3]    Store Utility\r\n\r\n         STORE UTILITIES\r\n                   ver 3.5\r\n\r\n     [5]    ICOMPLY File Preparation\r\n\r\n=====================================\r\n                ICOMPLY FILE\r\nPREPARE                     TO BE TRANSFERRED\r\n=====================================\r\n\r\n     Enter _Date <MmDdYy>:\r\n\r\n\r\nTHEN GET ICOMPLY FILE AT GEN CLERK\'s PC\r\n\r\n\r\n************************************************\r\nOLD STEP\r\n\r\nOPEN \"\"DOS prompt\"\" at BACKUP SERVER\r\nPumunta sa  \"\"backup date\"\"\r\nF:\\backup> cd MMDDYY(e.g 080120)\r\nF:\\backup\\date> dir icomply.dat\r\n\r\nTignan kung mayroong \"\"icomply.dat\"\"\r\n\r\nKung walang \"\"icomply.dat\"\" gawin ang sumusunod:\r\n\r\nF:\\backup\\date> copy con icomply.dat - enter\r\npress f6 then enter\r\n\r\nKung mayroon namang \"\"icomply.dat\"\" gawin ang sumusunod:\r\n\r\nF:\\backup\\date>pkzip iyYYMMDD.123 icomply.dat\r\n\r\n***PAALALA: maari mo makuha ang eksaktong \"\"iy file\"\" sa gen clerk nila****\r\n\r\nF:\\backup\\date>dir IY*.*\r\nF:\\backup\\date>copy IY200729.0123 \\user\\pos\\data\r\n\r\ntapos ipakuha mo na sa Clerk nila ang dokumento.\r\n\r\n\"', '2024-07-24 16:26:56', '2024-07-24 16:26:56', NULL),
(50, 'Unable to view DSSR report..', '\"Check if may Backup date.\r\n\r\nDATE: MMDDYY = 071420\r\n\r\n(CORRUPTED SERIES.DAT)\r\nCOPY SERIES.DAT AT PREVIOUS GOOD BACKUP DATE\r\n\r\nEXAMPLE:\r\nGOOD            : 050121\r\nCORRUPTED: 050221\r\n\r\nF:\\backup>cd 050121\r\nF:\\backup\\050121> copy series.dat \\backup\\050221\r\nOverwrite \'\\backup\\050221 (Yes/No/All/Quit) ? A\r\nF:\\backup\\050121>\r\n\r\nThen Generate DSSR dated 050221\r\n***************************************************************\r\nF:\\backup>cd date\r\n\r\nMag copy ng series.dat sa okay na backup date.\r\n\r\nF:\\backup\\050221>copy ..\\050121\\series.* .\r\n\r\nstep 2 pag ayaw pa din.\r\nF:\\backup\\050221>copy ..\\050121\\close.* .\r\nThen Generate DSSR dated 050221\"', '2024-07-24 16:30:10', '2024-07-24 16:30:10', NULL),
(51, 'REPRINTING OF PRODUCTIVITY REPORT..', '\"SOLUTION:\r\n(DOS PROMPT)\r\n\r\nDATE: MMDDYY = 060314\r\n\r\nF:\\backup>cd date\r\nF:\\backup\\date>copy prod.dat \\user\\pos\r\nOverwrite \'\\user\\pos\\PROD.DAT (Yes/No/All/Quit) ? A\r\nF:\\backup\\date>exitemu\r\n\r\nPrint the reports.....\"', '2024-07-24 16:30:28', '2024-07-24 16:30:28', NULL),
(52, 'CHMOD & CHOWN', '\"@ MAIN SERVER \r\nLOGIN: root\r\nPASSWORD: applied\r\n\r\nchmod -Rf 0777 /home/manager/main\r\nchown -Rf  manager:manager /home/manager/main\"', '2024-07-24 16:33:21', '2024-07-24 16:33:21', NULL),
(53, 'Remove Screen-saver & Auto Lock Screen on RX Terminal.', '\"INSTRUCTION: \r\nClick the GNOME TERMINAL beside the START MENU \r\nat Lower left of the monitor then type..\r\n\r\n=======================================\r\n[manager@backup-server ~]$ xscreensaver-demo   then(ENTER).\r\n\r\n-Display Modes-\r\n\r\n(For Remove Screen-saver).\r\nMode: Change to (Disable Screen Saver). \r\n\r\n(For Remove Auto Lock Screen).\r\nFind \"\"Lock Screen After\"\" then remove lang yung naka check sa box.\r\n\r\nKapag natanggal na yung check then close.\"', '2024-07-24 16:33:44', '2024-07-24 16:33:44', NULL),
(54, 'Installing All icons.', '\"RIGHT CLICK at DESKTOP (CLICK OPEN TERMINAL) \r\n\r\nTYPE:\r\n[manager@backup-server ~ ] $ su\r\nPassword:applied\r\n\r\n[root@backup-server manager ]# cd /root/mdc-script/Script\r\n[root@backup-server Script ]#./install-icon\"', '2024-07-24 16:34:14', '2024-07-24 16:34:14', NULL),
(55, '206 (DELETING ADVANCE DATE)', '\"CLICK DOS PROMPT \r\n\r\nTYPE:\r\n\r\nSTEP1:\r\n\r\nF:\\backup>cd\\user\\clerk\r\nF:\\user\\clerk>cdbf loc206.dbf\r\n\r\nSTEP2: Press Ctrl+End keys\r\n\r\n====================================================================================\r\n\r\n                                       FIGURE1:\r\n\r\n                                 F206_DTE / ff206_DTE\r\n                        #####################################\r\n                                      MM.DD.YYYY\r\n                                      05.13.2014\r\n                                      05.13.2014\r\n                                      05.14.2014\r\n                                      05.15.2014\r\n                                      05.16.2014\r\n                                      05.16.2014\r\n                                      05.17.2014 ---> present date\r\n                                      05.17.2014 ---> present date\r\n                        #####################################\r\n\r\n                                     FUNCTION KEYS:\r\n                                   =================\r\n                                      F4  = edit\r\n                                      F6  = insert\r\n                                      F8  = delete\r\n                                      F10 = quit\r\n                                      Esc = quit \r\n                                   =================\r\n\r\n\r\n\r\nF:\\iorder>exitemu\r\n\r\nSTEP7:\r\nRe-send the present date for \"\"206 Files/POS MASTER\"\" then log-off all\r\nPOS and TOS Terminals and perform Price Update at the Backup Server.\"', '2024-07-24 16:34:39', '2024-07-24 16:34:39', NULL),
(56, 'Database error prompted on TOS terminals.', '\"open dos prompt\r\n\r\ntype \r\ncd\\iorder\r\ndel drinv.dbf\r\ndel drinv1.idx\r\n\r\ndone.....\"', '2024-07-24 16:35:14', '2024-07-24 16:35:14', NULL),
(57, 'Clearing files (interrupted CLOSING PROCEDURE)', '\"Check if may Backup date.\r\n\r\nHow to Check Backup Date?\r\n\r\nOpen Dos Prompt\r\n\r\nF:\\Backup\r\ntype\r\nCd Date\r\n\r\nExample:\r\n\r\nF:\\Backup>cd 050918\r\nF:\\backup\\050918\\>dir\r\nCHECK FILES:\r\n\r\nF:\\backup\\050918\\>dir ej.*\r\nCHECK FILES:\r\n\r\nKung walang Backup date.\r\n\r\nClose Dos prompt\r\n\r\nedit check-file. from double to single\r\nHow to edit check-file\r\nRight sa gitna ng monitor and select Open Terminal\r\n\r\n[manager@Backup-server ~]# *vi check-file*\r\nchange *double to single*\r\nthen save and quit\r\n\r\nHow to save and quit?\r\n*press esc twice*\r\ntype \r\n*:wq!*\r\n\r\nPano kung may Backup date na?\r\n\r\nat Dos prompt\r\n\r\ntype:\r\nF:\\BACKUP> cd\\iorder\r\nF:\\IORDER> endoper\r\nF:\\IORDER> endoper1\r\nF:\\IORDER> del *.tmp\r\nF:\\IORDER> finish\r\n\r\nthen type (finish) for Price update(206)\r\n\r\nEffectivity date : \r\n\r\nafter ng 206 perform skipped clearing\r\nClick Skipped Clearing (dalawang maskara)\r\nEnd of shift day\r\n\r\n\r\n\r\nDone!!!!!\r\n\r\n\"', '2024-07-24 16:35:44', '2024-07-24 16:35:44', NULL),
(58, '\"File does not exist\" prompted upon closing procedure.', '\"(DOS PROMPT)\r\n\r\nF:\\backup>cd\\user\\pos\r\nF:\\user\\pos>cbdf loc206\r\n       PRESS: F10\r\n\r\nF:\\user\\pos>cd\\iorder\r\nF:\\iorder>cdbf ff206\r\n       PRESS: F10\r\n\r\nQUIT\"', '2024-07-24 16:36:11', '2024-07-24 16:36:11', NULL),
(59, '\"No database is in use prompted on TOS terminals\"', '\"At Main Server or Rx terminal or Backup Server \r\n\r\nCrtl + alt + F2                   /   on RX terminal open \'Gnome\' terminal\r\nLogin:root                     or     manager@rx-terminal# su\r\nPassword:applied        /       password: applied\r\n\r\n[root@main-server ~]# ssh 192.168.0.2(tos#) \r\nAre you sure you want to continue connecting (yes/no)? yes \r\nroot@192.168.0.2(tos#)\'s password: applied \r\n[root@localhost~]# cd /usr/share/dosemu/drive_z/ \r\n[root@localhostdrive_z]# ll (find qu_all.dbf) \r\n[root@localhost drive_z]# rm qu_all.dbf \r\nrm: remove regular empty file \'qu_all.dbf\'? y \r\n[root@localhost drive_z]# exit \r\n[root@main-server ~]# exit \r\n\r\nCtrl +alt F7\"', '2024-07-24 16:36:39', '2024-07-24 16:36:39', NULL),
(60, '\"Unable to get PWD file\" prompted on Gen clerk PC.', '\"open dos prompt\r\n\r\ndir pwd*.*\r\n\r\nmust have \r\n\r\npwd.dat\r\npwd16.dat\r\n\r\nif wala go to backup date directory and create file.\r\n\r\ne.g.\r\n\r\ned pwd.dat\r\ned pwd16.dat\"', '2024-07-24 16:37:04', '2024-07-24 16:37:04', NULL),
(61, 'Normal transaction from takeord asking osca id to POS.', '\"punch all osca transaction 1st. then stop osca on TOS terminal.\r\n\r\n\r\n\r\ncd\\iorder\r\ndel sr*.tmp\r\ndel pw*.tmp\"', '2024-07-24 16:37:29', '2024-07-24 16:37:29', NULL),
(62, '\"File Does not exist\" prompted on RX Terminal', '\"\r\n\"\"File Does not exist\"\" prompted on RX\r\n\r\nAt Rx terminal\r\npress ctrl + alt + F2\r\n\r\nlogin:root\r\npassword: applied\r\n\r\n[root@rx-terminal ~]# cd /home/manager/rx/iorder\r\n[root@rx-terminal iorder]# ll queue.*             \r\ncheck if queue.099 is existing	\r\n[root@rx-terminal iorder]#\r\nif not existing\r\n[root@rx-terminal iorder]# cp queue.001 queue.099\r\n[root@rx-terminal iorder]# vi queue.099\r\n	dapat	9999 ang laman nya..\r\n	pag 9999 na save mo na\r\n	press esc\r\n	:wq!\r\n[root@rx-terminal iorder]# exit\r\n\r\nthen press ctrl + alt + F7\r\n\r\ndone....\r\n\"', '2024-07-24 16:37:53', '2024-07-24 16:37:53', NULL),
(63, 'Invalid path or Filename prompted on Rx terminal', '\"At Rx terminal \r\npress ctrl + alt + F2 \r\n\r\nlogin:root \r\npassword: applied \r\n\r\n[root@rx-terminal ~]# cd /usr/share/dosemu/drive_z \r\n[root@rx-terminal drive_z]# rsync -av 192.168.0.21:/usr/share/dosemu/drive_z/qu_all.dbf . \r\nAre you sure you want to continue connecting (yes/no)? yes \r\nroot@192.168.0.21\'s password: applied \r\n[root@rx-terminal drive_z]# exit \r\n\r\npress ctrl + alt + F7 \r\n\r\nthen try.. :) \"', '2024-07-24 16:38:29', '2024-07-24 16:38:29', NULL),
(64, '\"Company does not exist\" Prompted on Takeord Terminals. suki icard transactions.', '\"STEP1:\r\nOpen TOOL BOX\r\nSelect number:   [2] Server/Manager\'s PC Option\r\nSelect number:   [1] SUKI ICard Option\r\nSelect number:   [1] Offline Record UPDATE\r\n\r\n[SELECT COMPANY OF ICARD]\r\n\r\n\r\n(Tunneling do not touch keyboard)\r\n\r\nSTEP2:\r\n(DOS PROMPT )\r\nF:\\backup>cd\\pos\r\nF:\\pos> dir acct*.*\r\nF:\\pos> copy acct26.txt account.sql\r\n\r\noverwrite? y\r\n\r\nTry to TOS Terminal\"', '2024-07-24 16:38:59', '2024-07-24 16:38:59', NULL),
(65, '\"This terminal is not properly identified\" prompted on RX Terminal', '\"\r\nAt Rx terminal\r\npress ctrl + alt + F2\r\n\r\nlogin:root\r\npassword: applied\r\n\r\n[root@rx-terminal ~]# cd /usr/share/dosemu/drive_z\r\n[root@rx-terminal drive_z]# rsync -av 192.168.0.21:/usr/share/dosemu/drive_z/quterm.dat .\r\nAre you sure you want to continue connecting (yes/no)? yes\r\nroot@192.168.0.21\'s password: applied\r\n[root@rx-terminal drive_z]# vi quterm.dat\r\n	dapat	9999 ang laman nya..\r\n	pag 9999 na save mo na\r\n	press esc\r\n	:wq!\r\n[root@rx-terminal drive_z]# exit\r\n\r\nthen press ctrl + alt + F7\r\nthen try.. :)\"', '2024-07-24 16:39:18', '2024-07-24 16:39:18', NULL),
(66, '\"not a database file\" prompted on Rx terminal', '\"At Rx terminal\r\npress ctrl + alt + F2\r\n\r\nlogin:root\r\npassword: applied\r\n\r\n[root@rx-terminal ~]# cd /usr/share/dosemu/drive_z\r\n[root@localhost drive_z]# rm qu_all.dbf\r\n[root@rx-terminal drive_z]# rsync -av 192.168.0.21:/usr/share/dosemu/drive_z/qu_all.dbf .\r\nAre you sure you want to continue connecting (yes/no)? yes\r\nroot@192.168.0.21\'s password: applied\r\n[root@rx-terminal drive_z]# exit\r\n\r\npress ctrl + alt + F7\r\n\r\nthen try.. :)\r\n\r\n\"', '2024-07-24 16:39:47', '2024-07-24 16:39:47', NULL),
(67, '\"Not A database file\" prompted on TOS terminal.', '\"At Main Server or Rx terminal or Backup Server\r\n\r\nCrtl + alt + F2\r\n\r\nLogin:root\r\nPassword:applied\r\n\r\n[root@main-server ~]# ssh 192.168.0.2(tos#)\r\nAre you sure you want to continue connecting (yes/no)? yes\r\nroot@192.168.0.2(tos#)\'s password: applied\r\n[root@localhost~]# cd /usr/share/dosemu/drive_z/\r\n[root@localhostdrive_z]# ll (find qu_all.dbf)\r\n[root@localhost drive_z]# rm qu_all.dbf\r\nrm: remove regular empty file \'qu_all.dbf\'? y\r\n[root@localhost drive_z]# exit\r\n[root@main-server ~]# exit\r\n\r\nCtrl +alt F7\"', '2024-07-24 16:40:05', '2024-07-24 16:40:05', NULL),
(68, '\"Database is not ordered\" Prompted on Takeord Terminals.', '\"NOTE: Log-off all Takeord Terminals and RX Terminal.\r\n\r\nSOLUTION 1: Re-index Location file at BACKUP SERVER\r\n\r\n(OPEN DOS PROMPT)\r\n\r\nSTEP1:\r\n\r\nF:\\backup>cd\\iorder\r\nF:\\iorder>utility\r\n> Password:tqbfjotld\r\n> 4.Entry/Update Item Location\r\n> Password:PASSWORD\r\n> Proceed ? Y/N : press Y\r\n> Reindex Location File\r\n> Proceed ? Y/N : press Y\r\n> 7.Quit\r\n> Quit\r\nF:\\iorder>exitemu\r\n\"', '2024-07-24 16:40:27', '2024-07-24 16:40:27', NULL),
(69, 'Suki Menu program not properly exit', '\"(DOS PROMPT) \r\nTYPE:\r\nF:\\backup> cd\\lsuki\r\nF:\\LSUKI> ini\r\n\r\nError corrected - ENTER ONLY\r\n\r\nF:\\lsuki>exitemu\"', '2024-07-24 16:40:45', '2024-07-24 16:40:45', NULL);
INSERT INTO `software` (`id`, `title`, `softdescription`, `created_at`, `updated_at`, `deleted_at`) VALUES
(70, 'Database Files problem - During OSCA / PWD transaction', '\" \r\n\r\n\r\n##########################################################################################\r\n            \"\"NOT A DATABASE FILE or NO DATABASE IS IN USE or\r\n                 INDEX DOES NOT MATCH DATABASE FILE\"\"\r\n##########################################################################################\r\n\r\n        Prompted on Takeord Terminal Screen During OSCA / PWD Transaction.\r\n\r\n==========================================================================================\r\n\r\nNOTE: Log-off All Takeord Terminals and RX Terminal.\r\n\r\nSOLUTION1:\r\n>Reindex OSCA Files....\r\n\r\nSTEP1:\r\nF:\\iorder>utility\r\n> Password:tqbfjotld\r\n> 1. Reindex Files\r\n> OSCA / PWD Files\r\n=============================================================================\r\n\r\nSOLUTION2:\r\nSTEP1:\r\nF:\\iorder>cdbf ordtaker.dbf\r\nremove all Y then F10\r\n\r\nFUNCTION KEYS:\r\n=================\r\n                F4  = edit\r\n                F6  = insert\r\n                F8  = delete\r\n                F10 = quit\r\n                Esc = quit\r\n\r\nPress F10 to Quit\r\n> The unregistered version does not save any options.\r\n> Press ENTER key\r\n\r\n=============================================================================\r\n\r\nSOLUTION3:\r\n> Restore The Previous Working IORDER and INV Files........\r\n\r\nSTEP1:\r\nI.\r\n\r\nF:\\backup>cd\\\r\nF:\\>ren inv inb\r\nF:\\>md inv\r\n\r\nII.\r\nF:\\>ren iorder ord\r\nF:\\>md inv\r\n\r\nSTEP2:\r\nF:\\>l:\r\nL:\\backup>cd\\\r\nL:\\>md inb\r\nL:\\>md ord\r\n\r\nSTEP3:\r\n[manager@backup-server]$ su\r\nPassword: applied\r\n[root@backup-server]# cd /mnt/ext-hd\r\n\r\nSTEP4:\r\n[root@backup-server ext-hd]# tar -xzvf YYYYMMDDHHMM\"\"FILENAME\"\"\r\n[root@backup-server ext-hd]# tar -xzvf 201405191015inv\r\n[root@backup-server ext-hd]# tar -xzvf 201405191015iorder\r\n\r\nSTEP5:\r\n[root@backup-server ext-hd]# cd inv\r\n[root@backup-server inv]# cp *.* /home/manager/main/inb -Rf\r\n[root@backup-server inv]# cd ..\r\n[root@backup-server ext-hd]# cd iorder\r\n[root@backup-server iorder]# cp *.* /home/manager/main/ord -Rf\r\n\r\nSTEP6:\r\nI.\r\n[root@backup-server iorder]# cd /home/manager/main/inb\r\n[root@backup-server inb]# chmod -Rf 777 *.*\r\n[root@backup-server inb]# chown manager:manager -Rf *.*\r\n\r\nII.\r\n[root@backup-server inb]# cd /home/manager/main/iorder\r\n[root@backup-server iorder]# chmod -Rf 777 *.*\r\n[root@backup-server iorder]# chown manager:manager -Rf *.*\r\n\r\nSTEP7:\r\nI.\r\nL:\\inb>copy *.* f:\\inv\r\nL:\\inb>cd\\ord\r\n\r\nII.\r\nL:\\ord>copy *.* f:\\iorder\r\nL:\\exitemu\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\"', '2024-07-24 16:41:11', '2024-07-24 16:41:11', NULL),
(71, '\"RX TERMINAL PRINTER WAS CONTINUOUS PRINTING\"', '\"INSTRUCTION:\r\nClick the GNOME TERMINAL beside the START MENU\r\nat Lower left of the monitor.\r\n\r\nmanager@rx-terminal$ su\r\n\r\npassword: applied\r\n\r\n[root@rx-terminal]$ lprm -\"', '2024-07-24 16:41:31', '2024-07-24 16:41:31', NULL),
(72, '\"INDEX DOES NOT MATCH DATABASE FILES\" Prompted on Takeord Terminals.', '\"NOTE: Log-off all Takeord Terminals and RX Terminal.\r\n\r\nSOLUTION1:\r\n\r\nSTEP1:\r\nF:\\backup>cd\\iorder\r\nF:\\iorder>utility\r\n> Password:tqbfjotld\r\n> 1. Reindex Files\r\n> Reindex all takeord Files\r\n> Quit\r\n> 7.Quit\r\nF:\\iorder>exitemu\r\n\r\n=============================================================================\r\n\r\nSOLUTION2:\r\n> Restore The Previous Working TAKEORD Files....\r\n\r\nSTEP1:\r\nF:\\>ren iorder ord\r\n\r\nSTEP2:\r\nF:\\>md iorder\r\n\r\nSTEP3:\r\nL:>md ord\r\n\r\nSTEP4:\r\n> Open Terminal or New Terminal and login as root.....\r\n[manager@backup-server]$ su\r\nPassword: applied\r\n[root@backup-server]# cd /mnt/ext-hd\r\n\r\nSTEP5:\r\n[root@backup-server ext-hd]# tar -xzvf YYYYMMDDHHMMiorder\r\n[root@backup-server ext-hd]# tar -xzvf 201405210915iorder\r\n\r\nSTEP6:\r\n[root@backup-server ext-hd]# cd iorder\r\n\r\nSTEP7:\r\n[root@backup-server iorder]# cp *.* /home/manager/main/ord -Rf\r\n[root@backup-server iorder]# cd /home/manager/main/ord\r\n\r\nSTEP8:\r\n[root@backup-server ord]# chmod -Rf 777 *.*\r\n[root@backup-server ord]# chown -Rf manager:manager *.*\r\n\r\nSTEP9:\r\nL:\\ord>copy *.* f:\\iorder\r\n\r\nNOTE:If not working TAR both INV and IORDER Files........\"', '2024-07-24 16:42:01', '2024-07-24 16:42:01', NULL),
(73, 'SUKI REDEEM 0 Point', '\"@BACKUP SERVER\r\n\r\n(open dos prompt)\r\n\r\nF:\\backup>cd\\pos\r\nF:\\pos>updat\r\n\"', '2024-07-24 16:42:19', '2024-07-24 16:42:19', NULL),
(74, '\"Duplicate Key\" - Prompted on POS..', '\"NOTE: POWER OFF the POS #\r\n\r\nSOLUTION:\r\nF:\\backup>cd\\pos\r\nF:\\pos>del tlog.00#\r\nF:\\pos>del tlogtmp.00#\r\nF:\\pos>del tlog00#.ix1\r\nF:\\pos>exitemu\r\n\"', '2024-07-24 16:42:38', '2024-07-24 16:42:38', NULL),
(75, '\"Enter Dept/Class\" - Prompted on POS terminals upon scanning items -- TarPLU..', '\"==============================================================================================\r\n                      NOTE: Log-off all POS terminals only.\r\n===================================================================================\r\n\r\n>>>>> Restore T\"', '2024-07-24 16:42:58', '2024-07-24 16:42:58', NULL),
(76, '\"Order number has been recalled\" prompted on POS terminals', '\"NOTE: Log-off all POS Terminals.....\r\n\r\nSOLUTION:\r\nF:\\backup>cd\\pos\r\nF:\\pos>del rco*.*\r\nF:\\pos>cd\\iorder\r\nF:\\iorder>endoper\r\nF:\\iorder>endoper1\r\nF:\\iorder>del *.tmp\r\nF:\\iorder>exitemu\r\n\r\n\"', '2024-07-24 16:43:30', '2024-07-24 16:43:30', NULL),
(77, '\"Enter Dept/Class\" - Prompted on POS terminals upon scanning items..', '\"SOLUTION1:\r\n##############################################################################\r\nInstruct to reprocess the present date for 206 files from Gen. Clerk\'s PC\r\n(NOTE: Processing of 206 files almost 1 HOUR or above)\r\nthen send the POS MASTER to the Main Server and log-off all\r\nPOS and TOS terminals and perform price update at the\r\nBackup Server.\r\n##############################################################################\r\n\r\n\r\nSOLUTION2:\r\nSTEP1:\r\nF:\\backup>cd\\user\\clerk\r\nF:\\user\\clerk>cdbf loc206.dbf\r\n\r\nSTEP2: Press Ctrl+End keys\r\n\r\n====================================================================================\r\n\r\n                                       FIGURE1:\r\n\r\n                                 F206_DTE / ff206_DTE\r\n                        #####################################\r\n                                      MM.DD.YYYY\r\n                                      05.13.2014\r\n                                      05.13.2014\r\n                                      05.14.2014\r\n                                      05.15.2014\r\n                                      05.16.2014\r\n                                      05.16.2014\r\n                                      05.17.2014 ---> present date\r\n                                      05.17.2014 ---> present date\r\n                        #####################################\r\n\r\n                                     FUNCTION KEYS:\r\n                                   =================\r\n                                      F4  = edit\r\n                                      F6  = insert\r\n                                      F8  = delete\r\n                                      F10 = quit\r\n                                      Esc = quit \r\n                                   =================\r\n\r\n==============================================================================\r\nSTEP3: Delete the double dates.\r\n> Press F8 to delete the dates\r\n> Press F10 to Quit\r\n> The unregistered version does not save any options.\r\n> Press ENTER key\r\n\r\n=============================================================================\r\n                                        FIGURE2:\r\n\r\n                  AFTER DELETING:\r\n                                 F206_DTE / ff206_DTE\r\n                        #####################################      \r\n                                      MM.DD.YYYY\r\n                                      05.13.2014\r\n                                      05.14.2014\r\n                                      05.15.2014\r\n                                      05.16.2014\r\n                        #####################################      \r\n\r\n=============================================================================\r\nSTEP4:\r\nF:\\user\\clerk>cd\\iorder\r\nF:\\iorder>cdbf ff206.dbf\r\n\r\nSTEP5: Press Ctrl+End keys\r\nSTEP6: Check FIGURE1 and FIGURE2\r\n\r\nF:\\iorder>exitemu\r\n\r\nSTEP7:\r\nRe-send the present date for \"\"206 Files/POS MASTER\"\" then log-off all\r\nPOS and TOS Terminals and perform Price Update at the Backup Server.\r\n============================================================================\r\nNOTE:\r\nIf SOLUTION1 and SOLUTION2 not working\r\nCheck the tarplu text file.\"', '2024-07-24 16:43:47', '2024-07-24 16:43:47', NULL),
(78, 'Opening and Closing Procedure @ Main server', '\"How To Perform Opening and Closing Procedure on Main Server\r\n\r\nPress Ctrl+Alt+F2\r\n\r\nMain Server Login: root\r\nPassword: applied\r\n[root@main-server~]#./byPassManPC.sh\r\n\r\n        Manager\'s PC Not Detected!!!\r\n        By Pass Manager\'s PC Permitted...\r\n\r\n[manager@main-server~]#./mercuryMenu.sh\r\n                                 \r\n                    BRANCH MENU Ver 1.0\r\n\r\n                ENTER YOUR MENU CHOICE (1-0)\r\n\r\n                 [1] Store Opening Procedure\r\n                 [2] Reports Generation\r\n                 [3] POS Inquiries\r\n                 [4] DOS Utilities\r\n                 [5] Tool Box\r\n                 [6] Software Updates\r\n                 [7] Store Closing Procedure\r\n                 [0] Exit/Close\r\n\r\nNOTE: Only 1, 4 and 7 ready function the rest to be follow.\r\n\r\n[manager@main-server~]#exit\r\n[root@main-server~]#exit\r\n\"', '2024-07-24 16:44:05', '2024-07-24 16:44:05', NULL),
(79, 'Copying Icons to Desktop', '\"Copy icon to desktop or panel\r\n\r\nAt Backup Server\r\n\r\nRIGHT CLICK then Open Terminal\r\nTYPE:\r\nsu\r\npassword:applied\r\n\r\nOR\r\n\r\nPress ctrl + alt + F2\r\nTYPE\r\nlogin:root\r\npassword: applied\r\n\r\n[root@Backup server ~]# cd /root/mdc-script/desktop\r\n[root@Backup server desktop]# cp -af Activate\\ Backup\\ Server.desktop /home/manager/Desktop/\r\n[root@Backup server desktop]# exit\r\n\r\ncp -af filename /home/manager/Desktop/\r\n\r\nList of icons File name\r\nActivate\\ Backup\\ Server.desktop           	\r\nBack-End\\ Report.desktop		         \r\nClosing\\ Procedure.desktop		\r\nDos\\ Prompt.desktop		\r\nInstallation\\ Diskette.desktop		\r\nL-sukimenu.desktop			\r\nOpening\\ Procedure.desktop		\r\nPerform\\ Price\\ Update.desktop	\r\nPrinting\\ of\\ Reports..desktop		\r\nProfile\\ Personalization.desktop\r\nShutdown\\ Main\\ & Backup\\ Server.desktop\r\nSkipped\\ Clearing.desktop\r\nSoftware\\ Update.desktop\r\nTakeord\\ Onhand.desktop\r\nTool\\ Box.desktop\r\nView\\ Current\\ Sales.desktop\r\nView\\ F206\\ Update.desktop\r\nView\\ Thisday\\ Sales.desktop\r\n\r\nTO RETURN TO DESKTOP\r\nPRESS:\r\npress ctrl + alt + F7\r\n\r\n\"', '2024-07-24 16:44:24', '2024-07-24 16:44:24', NULL),
(80, 'Cashier Functions.', '\"PROFILE PERSONALIZATION\r\n\r\nCASHIER CODE                    999901\r\nCASHIER NAME                    PLSI\r\nEMPLOYEE NUMBER           999901\r\nRECEIPT IDENTIFICATION   PLSI\r\n\r\n\r\nCashier Function.\r\n\r\n5\r\n6\r\n11\r\n12\r\n13\r\n15\r\n18\r\n21\r\n\r\nEND OF FILE\r\n\r\n\r\n\r\n\r\n\r\n\"', '2024-07-24 16:44:41', '2024-07-24 16:44:41', NULL),
(81, 'Kernel panic @ Main Server and Backup Server', '\"power on cpu then quickly press delete or F2\r\n\r\n:bios/cmos setup:\r\ngo to peripherals\r\nunder peripherals\r\nchange sata mode selection from ide to ahci\r\nthen press F10\r\nselect YES to save and restart.\r\n\"', '2024-07-24 16:45:51', '2024-07-24 16:45:51', NULL),
(82, 'Onhand problem - \"str.str\"', '\"copy str.str from L:\\iorder\r\nor\r\nopen terminal \r\n\r\ncd /root/mdc-script/main/iorder\r\n\r\n(COPY TO MAIN SERVER)\r\ncp -fp str.str /home/manager/backup/iorder/\r\n\r\n(COPY TO BACKUP SERVER)\r\ncp -fp str.str /home/manager/main/iorder/\r\n\r\n\r\nOPTION 2\r\n(cp str* /home/manager/main/iorder/)\"', '2024-07-24 16:46:23', '2024-07-24 16:46:23', NULL),
(83, '\"Unclean Log\" - Printed on the Backup Server..', '\"STEP1:\r\n> Right Click on the Screen and Click Open Terminal and login as root...\r\n\r\nSTEP2:\r\n[manager@backup-server]$ su\r\nPassword: applied\r\n\r\nSTEP3:\r\n[root@backup-server]# cd /home/manager/backup\r\n\r\nSTEP4:\r\n[root@backup-server backup]# ls scan.*\r\n[root@backup-server backup]# rm -Rf scan.*\r\n[root@backup-server backup]# ls scan.*\r\n[root@backup-server backup]# exit\r\n[manager@backu-server]$ exit\r\n\r\n===============================================\r\n\r\nALTERNATE COMMAND at MAIN SERVER\r\n\r\nSTEP1:\r\nMain Server Login: root\r\nPassword: applied\r\n\r\nSTEP2:\r\n[root@main-server]# cd /home/manager/main\r\n[root@main-servermain]# ls scan.*\r\n[root@main-servermain]# rm -Rf scan.*\r\n[root@main-servermain]# ls scan.*\r\n[root@main-servermain]# exit\r\n\"', '2024-07-24 16:46:45', '2024-07-24 16:46:45', NULL),
(84, 'Suki Claim Reports - \"Clear Temporary Table\"..', '\" \"\"CLEAR TEMPORARY TABLE\"\"  Upon printing of SUKICLAIM reports.\r\n    \r\n         Ù\r\n\r\nSOLUTION1:\r\nSTEP1:\r\nF:\\backup>cd\\lsuki\r\nF:\\lsuki>cdbf sukimstr.dbf\r\n\r\n=============================================\r\nNOTE: correct the error prompt on the screen.\r\n=============================================\r\n\r\nSTEP2:\r\nF:\\lsuki>lsuki\r\n@ Suki Menu\r\n> Utilities\r\n> Initialization (Y)\r\n> Reindex (Y)\r\n> Close>exit\r\n\r\nSTEP3\r\nF:\\lsuki>ini\r\n\r\n==========================================================================================\r\n\r\nSOLUTION2:\r\n\r\nSTEP1:\r\nF:\\backup>cd\\lsuki\\database\r\nF:\\lsuki\\database>dir *.dbf\r\n\r\nNOTE: CDBF the given files\r\n\r\n       ==============\r\n        CLAIM    DBF\r\n        SUKI     DBF\r\n        CLPLUS   DBF\r\n        TRPLUS   DBF     \r\n        SKPLUS   DBF        \r\n        SUKITRAN DBF\r\n        SUKICLM  DBF\r\n        IMPDATE  DBF\r\n        CHKDTE   DBF\r\n        TRAN     DBF\r\n       ==============\r\n\r\nF:\\lsuki\\database>cdbf \"\"filename.dbf\"\"\r\n\r\nEXAMPLE:\r\nF:\\lsuki\\database>cdbf claim.dbf\r\n\r\nFUNCTION KEYS:\r\n                                   =================\r\n                                      F4  = edit\r\n                                      F6  = insert\r\n                                      F8  = delete\r\n                                      F10 = quit\r\n                                      Esc = quit \r\n                                   =================\r\n\r\n==============================================\r\nNOTE: correct the error prompt on the screen.\r\n==============================================\r\n\r\nSTEP2:\r\nF:\\lsuki\\databse>cd..\r\nF:\\lsuki>lsuki\r\n@ Suki Menu\r\n> Utilities\r\n> Initialization (Y)\r\n> Reindex (Y)\r\n> Close>exit\r\n\r\nSTEP3:\r\nF:\\lsuki>ini\r\n\r\n FUNCTION KEYS:\r\n                                   =================\r\n                                      F4  = edit\r\n                                      F6  = insert\r\n                                      F8  = delete\r\n                                      F10 = quit\r\n                                      Esc = quit \r\n                                   =================\"', '2024-07-24 16:47:12', '2024-07-24 16:47:12', NULL),
(85, 'Price Update(206) @ Backup Server - \"Index Does not match database file\"..', '\"==================================================================================================================\r\n        Prompted During Performing Price Update at the Backup Server.\r\n======================================================================\"', '2024-07-24 16:47:31', '2024-07-24 16:47:31', NULL),
(86, 'GIFT CERTIFICATE Reports - \"Database error\"..', '\"\"\"NOT A DATABASE FILE\"\" Upon Printing of GIFT CERTIFICATE Reports\r\n\r\nSOLUTION:\r\nF:\\backup>cd\\user\\pos\r\nF:\\user\\pos>del giftmast.dbf\r\nF:\\user\\pos>del gcsumary.dbf\r\nF:\\user\\pos>del gifttran.dbf\r\nF:\\backup>exitemu\r\n\r\n\"\"Index dos not match database file\"\" Upon Printing of GIFT CERTIFICATE Reports. \r\n\r\nSOLUTION:\r\nF:\\backup>cd\\user\\pos\r\nF:\\user\\pos>del giftmast.idx\r\nF:\\user\\pos>del gcsumary.idx\r\nF:\\user\\pos>del gifttran.idx\r\nF:\\backup>exitemu\r\n\r\n\"', '2024-07-24 16:47:51', '2024-07-24 16:47:51', NULL),
(87, 'E-COUPON Reports \"NOT A DATABASE FILE..', '\"SOLUTION:\r\nF:\\backup>cd\\user\\pos\r\nF:\\user\\pos>del ecptran.dbf\r\nF:\\user\\pos>del refmast.dbf\r\nF:\\user\\pos>exitemu\r\n\r\n\"', '2024-07-24 16:48:08', '2024-07-24 16:48:08', NULL),
(88, '\"REPRINTING OF DEPARTMENT AND CLASSIFICATION REPORTS; Retrieval of The DPTCLS Files\"', '\"SOLUTION:\r\n@BACKUP SERVER\r\n\r\n(open dos prompt)\r\n\r\nDATE: MMDDYY = 010122\r\n\r\nF:\\backup>cd 010122\r\nF:\\backup\\date>copy dptcls.* \\user\\pos\r\n\r\nOverwrite \'\\user\\pos\\DPTCLS.IX1 (Yes/No/All/Quit) ? A\r\n\r\nF:\\backup\\date>exitemu\r\n\r\nPrint the reports.....\r\n\r\n\r\n\r\n***************************************************************************\r\n\r\n\r\n\r\n\r\n\"\"NO DATA PROMPTED ON PRINTING\"\"\r\n\r\n>>>>> Retrieval of The DPTCLS Files....\r\n\r\nSTEP1:\r\n>open terminal at the Backup Server\r\n\r\nSTEP2:\r\n[manager@backup-server]$ su\r\nPassword: applied\r\n\r\nSTEP3:\r\n[root@backup-server]# cd /mnt/ext-hd\r\n\r\nSTEP4:\r\n\r\nFORMAT:\r\n[root@backup-server]# ls\r\n\r\nFIND: StoreClose or last YYYYMMDDHHMMpos\r\n\r\nEXAMPLE:\r\n[root@backup-server ext-hd]# tar -xzvf 202206202100pos\r\nor\r\n[root@backup-server ext-hd]# tar -xzvf sc092422-0403\r\nSTEP5:\r\n\r\n[root@backup-server ext-hd]# ls\r\n\r\n[root@backup-server ext-hd]# cd pos\r\nor\r\n[root@backup-server ext-hd]# cd Unzip\r\n\r\nSTEP6:\r\n[root@backup-server pos]# cp -Rf dptcls* /home/manager/backup/user/pos\r\nand\r\nroot@backup-server pos]# cp –Rf dptcls* /home/manager/main/backup/062022\r\nand to backup date: example\r\n[root@backup-server pos]# cp –Rf dptcls* /home/manager/backup/backup/062022\r\nrsync -av dptcls.* 192.168.0.10:/home/manager/main/backup/100623\r\n\r\nSTEP7:\r\n[root@backup-server ext-hd]# exit\r\n[manager@backup-server]$ exit\r\n\r\nSTEP8: Print the reports.....\r\n\"', '2024-07-24 16:48:33', '2024-07-24 16:48:33', NULL),
(89, '*INCORRECT DATE AND TIME*', '\"NOTE: log-off all Terminals.\r\n\r\n@MAIN SERVER\r\nMain Server Login: root\r\nMain Server Pass:  applied\r\n===============================================\r\nSTEP1: DATE\r\nroot@ Main Server]# date -s YYYYMMDD\r\nroot@ Main Server]# date -s 20140206\r\n\r\nSTEP2: TIME\r\nroot@ Main Server]# date -s HH:MM:SS\r\nroot@ Main Server]# date -s 09:10:00\r\n\r\n\r\nSTEP3: Restart All POS & Takeord.\r\n\r\n===============================================\r\nAlternate command for Changing DATE & TIME.....\r\n\r\nroot@ Main Server]# date -s \"\"YYYYMMDD HH:MM:SS\"\"\r\nroot@ Main Server]# date -s \"\"20140415 09:10:00\"\"\r\n\r\nChecking Date & Time\r\n[root@ Main Server]# date\r\n\r\n\r\nThen Restart All POS & Takeord.\"', '2024-07-24 16:48:52', '2024-07-24 16:48:52', NULL),
(90, 'Barcode / Scan Coupon Report..', '\"Problem: #1\r\n#######################################\r\n   \"\"INDEX DOES MATCH DATABASE FILES\"\"\r\n#######################################\r\n\r\nPrompted on the Backup Server screen upon\r\nPrinting of daily BARCODED/SCAN COUPON report.\r\n\r\nSOLUTION:\r\n\r\nF:\\backup>cd\\user\\pos\r\nF:user\\pos>del *.idx\r\nF:\\user\\pos>exitemu\r\n\r\n>>> Print the report....\r\n\r\n==============================================================================\r\nProblem: #2\r\n#######################################\r\n   \"\"NOT A DATABASE FILE\"\"\r\n#######################################\r\nPrompted on the Backup Server screen upon\r\nPrinting of daily BARCODED/SCAN COUPON report.\r\n\r\nSOLUTION:\r\n\r\nF:\\backup>cd\\user\\pos\r\nF:\\user\\pos>del brmast.dbf\r\nF:\\user\\pos>del barcmast.dbf\r\nF:\\user\\pos>del barctran.dbf\r\nF:\\user\\pos>exitemu\r\n\r\n>>> Print the report.....\r\n\r\n===============================================================================\r\n\r\nProblem: #3\r\n#####################################################\r\n     \"\"FILE BRMAST.DBF/BRMAST.IDX DOES NOT EXIST\"\"\r\n#####################################################\r\nPrompted on the Backup Server screen upon\r\nPrinting of daily BARCODED/SCAN COUPON report.\r\n\r\nSOLUTION:\r\n\r\nF:\\backup>cd\\user\\pos\r\nF:\\user\\pos>barcmast\r\nF:\\user\\pos>exitemu\r\n\r\n>>> Print the report......\"', '2024-07-24 16:49:11', '2024-07-24 16:49:11', NULL),
(91, '\"Give Root Password\" prompted on Main or Backup server.', '\"TYPE:\r\napplied\r\n\r\n\r\nRepair file system number #1:\r\nTYPE:fsck\r\n\r\nAll appear with Question mark;\r\nY enter\r\n\r\n\r\nRepair file system number #2:\r\nTYPE:fsck\r\n\r\n\r\nRepair file system number #3:\r\nTYPE:fsck\r\n\r\n\r\nRepair file system number #4:\r\nPress\r\nCtrl+D\r\n\r\nNOTE:\r\nPerform Opening procedure at Backup server if Opening done at Main server.\"', '2024-07-24 16:49:31', '2024-07-24 16:49:31', NULL),
(92, 'Documents has no pages23', '<p>dfdfdfdfd</p><div class=\"attachment-gallery attachment-gallery--2\"><figure data-trix-attachment=\"{&quot;contentType&quot;:&quot;image/png&quot;,&quot;filename&quot;:&quot;Ideaserv (1).PNG&quot;,&quot;filesize&quot;:65375,&quot;height&quot;:305,&quot;href&quot;:&quot;/storage/storage/X0ZM0jDbPxVfeJOW0TYk6ejrfuzxW74YmlIcYgcM.png&quot;,&quot;url&quot;:&quot;/storage/storage/X0ZM0jDbPxVfeJOW0TYk6ejrfuzxW74YmlIcYgcM.png&quot;,&quot;width&quot;:482}\" data-trix-content-type=\"image/png\" data-trix-attributes=\"{&quot;presentation&quot;:&quot;gallery&quot;}\" class=\"attachment attachment--preview attachment--png\"><a href=\"/storage/storage/X0ZM0jDbPxVfeJOW0TYk6ejrfuzxW74YmlIcYgcM.png\"><img src=\"/storage/storage/X0ZM0jDbPxVfeJOW0TYk6ejrfuzxW74YmlIcYgcM.png\" width=\"482\" height=\"305\"><figcaption class=\"attachment__caption\"><span class=\"attachment__name\">Ideaserv (1).PNG</span> <span class=\"attachment__size\">63.84 KB</span></figcaption></a></figure></div>', '2025-03-25 21:11:43', '2025-03-25 22:41:40', '2025-03-25 22:41:40'),
